using System; using System.IO; using System.Linq; using System.Collections.Generic; using System.Globalization; using System.Text.RegularExpressions; using System.Web.Script.Serialization;
public class ImpactAnalysis {
class Contact { public string Shop,Service,Task; public DateTime Date; public string[] Row; public bool Revenue; }
class Order { public string Shop,Id; public DateTime Open,Posted; public List<Contact> Contacts=new List<Contact>(); public List<Tuple<DateTime,double>> Amounts=new List<Tuple<DateTime,double>>(); }
class Task { public Contact Last; public bool Converted; }
public class Bucket { public string shop,service,month; public int contacts,human,tasks,matureTasks,converted,convertedMature,appointments,visits,pricedOrders; public double revenue; }
static Regex ro=new Regex(@"([^,\s]+)\s*\((\d{2}-\d{2}-\d{2})\)",RegexOptions.Compiled);
static double Num(string s) {double v;return double.TryParse(s,NumberStyles.Any,CultureInfo.InvariantCulture,out v)?v:0;}
static DateTime D(string s) {return DateTime.FromOADate(Num(s));}
static string Group(string s) { if(s.StartsWith("Reminder Oil Change"))return "Oil Change Reminder";if(s.StartsWith("Reminder BG"))return "BG Services";if(s=="Reminder State Inspection")return "State Inspection";return string.IsNullOrEmpty(s)?"Unassigned":s; }
static Dictionary<string,Bucket> buckets=new Dictionary<string,Bucket>();
static Bucket B(Contact c,DateTime d) {string m=d.ToString("yyyy-MM"),k=c.Shop+"|"+c.Service+"|"+m;Bucket b;if(!buckets.TryGetValue(k,out b)){b=new Bucket{shop=c.Shop,service=c.Service,month=m};buckets[k]=b;}return b;}
public static void Run(List<string[]> rows,List<string[]> dates,string output) {
buckets.Clear();var contacts=new List<Contact>();var seen=new HashSet<string>();var tasks=new Dictionary<string,Task>();var orders=new Dictionary<string,Order>();var appts=new Dictionary<string,Contact>();int duplicateRows=0,missingTasks=0,multiAmountRows=0;DateTime cutoff=DateTime.MinValue,start=DateTime.MaxValue;
var nonRevenue=new HashSet<string>(new[]{"Next Day Satisfaction","Returning Lost Customer","Returning Lost Vehicle","Welcome New Customer"},StringComparer.OrdinalIgnoreCase);
var allowed=new HashSet<string>(new[]{"Oil Change Reminder","Pre-Book Oil Change","Service Overdue","Warranty Inspection","State Inspection","Pre-Book State Inspection","BG Services","Reservation No Show","Retention Re-Engage","No Recent Visits","Reopened Missed Sale","Welcome New Vehicle"});
foreach(var r in rows.Skip(1)) {if(string.IsNullOrEmpty(r[0])||Num(r[3])<40000)continue;string fingerprint=string.Join("\t",r);if(!seen.Add(fingerprint)){duplicateRows++;continue;}var c=new Contact{Shop=r[0],Service=Group(r[14]??""),Task=r[11],Date=D(r[3]),Row=r};c.Revenue=allowed.Contains(c.Service)&&!nonRevenue.Contains(c.Service);contacts.Add(c);if(c.Date>cutoff)cutoff=c.Date;if(c.Date<start)start=c.Date;
var b=B(c,c.Date);b.contacts++;if(r[6]=="Human")b.human++;
if(c.Revenue){if(!string.IsNullOrEmpty(c.Task)){string key=c.Shop+"|"+c.Task;Task t;if(!tasks.TryGetValue(key,out t)){t=new Task();tasks[key]=t;}if(t.Last==null||c.Date>t.Last.Date)t.Last=c;}else missingTasks++;}
foreach(string id in (r[17]??"").Split(',')){string aid=id.Trim();if(aid.Length==0)continue;string k=c.Shop+"|"+aid;Contact prev;if(!appts.TryGetValue(k,out prev)||c.Date>prev.Date)appts[k]=c;}
var opens=ro.Matches(r[19]??"");var posts=ro.Matches(r[21]??"");foreach(Match m in opens){string id=m.Groups[1].Value,k=c.Shop+"|"+id;Order o;if(!orders.TryGetValue(k,out o)){o=new Order{Shop=c.Shop,Id=id};orders[k]=o;}DateTime dt=DateTime.ParseExact(m.Groups[2].Value,"MM-dd-yy",CultureInfo.InvariantCulture);if(o.Open==default(DateTime)||dt<o.Open)o.Open=dt;o.Contacts.Add(c);}
foreach(Match m in posts){string id=m.Groups[1].Value,k=c.Shop+"|"+id;Order o;if(!orders.TryGetValue(k,out o)){o=new Order{Shop=c.Shop,Id=id};orders[k]=o;}DateTime dt=DateTime.ParseExact(m.Groups[2].Value,"MM-dd-yy",CultureInfo.InvariantCulture);if(o.Posted==default(DateTime)||dt<o.Posted)o.Posted=dt;o.Contacts.Add(c);if(posts.Count==1&&!string.IsNullOrEmpty(r[23]))o.Amounts.Add(Tuple.Create(c.Date,Num(r[23])));}
if(posts.Count>1&&Num(r[23])!=0)multiAmountRows++;
}
cutoff=cutoff.Date;int outsideWindow=0,relationshipOnly=0,noOpen=0,afterCutoff=0,unpriced=0,conflicts=0,qualified=0,notPosted=0,unresolvedAmounts=0;double total=0;
var ledger=new List<string>();ledger.Add("Shop,RO ID,Opened date,Posted date,Credited service,Credited task,Qualifying contact date,Counted revenue,Status");
foreach(var o in orders.Values){string reason="",service="",taskID="",contactDate="";double credited=0;if(o.Open==default(DateTime)){noOpen++;reason="Missing opening date";}else if(o.Open>cutoff){afterCutoff++;reason="Opened after cutoff";}else {
var eligible=o.Contacts.Where(c=>c.Date.Date<=o.Open&&(o.Open-c.Date.Date).TotalDays<=30).ToList();if(eligible.Count==0){outsideWindow++;reason="No linked contact within 30 days";}else {var winning=eligible.Where(c=>c.Revenue).OrderByDescending(c=>c.Date).ThenBy(c=>c.Task).FirstOrDefault();if(winning==null){relationshipOnly++;reason="Only non-revenue contacts qualify";}else {qualified++;service=winning.Service;taskID=winning.Task;contactDate=winning.Date.ToString("yyyy-MM-dd HH:mm");B(winning,o.Open).visits++;Task task;if(!string.IsNullOrEmpty(winning.Task)&&tasks.TryGetValue(winning.Shop+"|"+winning.Task,out task))task.Converted=true;
if(o.Posted==default(DateTime)||o.Posted>cutoff){unpriced++;notPosted++;reason="Qualifying visit; not posted by cutoff";}else if(o.Amounts.Count==0){unpriced++;unresolvedAmounts++;reason="Qualifying visit; individual amount unresolved";}else {var distinct=o.Amounts.Select(a=>Math.Round(a.Item2,2)).Distinct().ToList();if(distinct.Count>1){conflicts++;unpriced++;unresolvedAmounts++;reason="Qualifying visit; conflicting amounts";}else {credited=distinct[0];var b=B(winning,o.Posted);b.revenue+=credited;b.pricedOrders++;total+=credited;reason="Qualifying visit; verified revenue";}}}}}
ledger.Add(string.Join(",",new[]{o.Shop,o.Id,o.Open==default(DateTime)?"":o.Open.ToString("yyyy-MM-dd"),o.Posted==default(DateTime)?"":o.Posted.ToString("yyyy-MM-dd"),service,taskID,contactDate,credited.ToString("F2",CultureInfo.InvariantCulture),reason}.Select(s=>"\""+(s??"").Replace("\"","\"\"")+"\"")));
}
foreach(var t in tasks.Values){var b=B(t.Last,t.Last.Date);b.tasks++;if(t.Converted)b.converted++;if(t.Last.Date.Date<=cutoff.AddDays(-30)){b.matureTasks++;if(t.Converted)b.convertedMature++;}}
foreach(var a in appts.Values)B(a,a.Date).appointments++;
var active=dates.Skip(1).Where(r=>!string.IsNullOrEmpty(r[0])).Select(r=>new {shop=r[0],start=D(r[1]).ToString("yyyy-MM-dd"),end=string.IsNullOrEmpty(r[2])?null:D(r[2]).ToString("yyyy-MM-dd")}).ToArray();
var result=new {source="shop_story.xlsx",start=start.ToString("yyyy-MM-dd"),cutoff=cutoff.ToString("yyyy-MM-dd"),shops=contacts.Select(c=>c.Shop).Distinct().OrderBy(x=>x).ToArray(),active=active,services=contacts.Select(c=>c.Service).Distinct().OrderBy(x=>x).ToArray(),revenueServices=allowed.ToArray(),relationshipServices=nonRevenue.ToArray(),buckets=buckets.Values.OrderBy(b=>b.month).ThenBy(b=>b.shop).ToArray(),audit=new {sourceRows=rows.Count-1,contacts=contacts.Count,duplicateRows=duplicateRows,uniqueROs=orders.Count,qualifiedVisits=qualified,verifiedRevenue=Math.Round(total,2),uniqueAppointments=appts.Count,uniqueRevenueTasks=tasks.Count,missingRevenueTaskIDs=missingTasks,roOutsideWindow=outsideWindow,relationshipOnlyROs=relationshipOnly,missingOpenDate=noOpen,roAfterCutoff=afterCutoff,unpricedQualifiedROs=unpriced,notPostedByCutoff=notPosted,unresolvedIndividualAmounts=unresolvedAmounts,conflictingROAmounts=conflicts,multiROAmountRows=multiAmountRows},pricing=new {baseFee=999,crmFee=699,perContact=5}};
var serializer=new JavaScriptSerializer{MaxJsonLength=int.MaxValue};File.WriteAllText(output,"window.IMPACT_DATA="+serializer.Serialize(result)+";",new System.Text.UTF8Encoding(false));
Console.WriteLine(serializer.Serialize(result.audit));Console.WriteLine("Observed period: "+result.start+" to "+result.cutoff+"; Shops: "+result.shops.Length+"; Buckets: "+buckets.Count);
File.WriteAllLines(Path.Combine(Path.GetDirectoryName(output),"..","..","Shop Story RO Ledger.csv"),ledger,new System.Text.UTF8Encoding(true));
}
}
